INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (104,'vocabulary','checkout','circulation.audit_loan__t â€” use for counting checkouts. Each checkout is a separate row. Filter with: loan__action IN (\'checkedout\', \'checkedOutThroughOverride\'). Join items via loan__item_id. loan_date is loan__loan_date. Do NOT use circulation.loan__t for counting checkouts â€” it only stores the current state of each loan.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (105,'vocabulary','loan','circulation.audit_loan__t â€” the audit log of all loan events. Use for counting loan activity. Columns use the loan__ prefix: loan__item_id, loan__action, loan__loan_date, loan__due_date, loan__return_date. Use circulation.loan__t ONLY for current-state queries (e.g. what is currently checked out right now).',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (106,'vocabulary','checkin','circulation.audit_loan__t where loan__action = \'checkedin\' â€” for counting checkins. Or circulation.check_in__t for check-in transaction records. Do NOT use circulation.loan__t.return_date for counting returns â€” loan__t only shows the current state.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-03-06 09:49:37');
