INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (128,'vocabulary','circulation log','audit.circulation_logs__t â€” audit trail of circulation events.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (129,'vocabulary','circulating','circulation.audit_loan__t â€” count loan events to measure circulation. Filter with loan__action IN (\'checkedout\', \'checkedOutThroughOverride\'). Join loan__item_id â†’ inventory.item__t â†’ effective_location_id â†’ location__t â†’ loclibrary__t â†’ loccampus__t for location context.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (130,'vocabulary','book','inventory.material_type__t where LOWER(name) = \'book\'. The database stores \'Book\' (capitalized). Always use case-insensitive comparison.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (131,'vocabulary','equipment','inventory.material_type__t where LOWER(name) LIKE \'%equipment%\'. Exclude with AND LOWER(imt.name) NOT LIKE \'%equipment%\'.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 20:39:13','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (132,'example',NULL,NULL,'Show me all materials purchased in the last 90 days grouped by material type purchased by Smith College','SELECT imt.name AS material_type_name, SUM(COALESCE(pol.cost__quantity_physical, 1)) AS total_purchased FROM orders.po_line__t AS pol JOIN orders.purchase_order__t AS po ON pol.purchase_order_id = po.id JOIN inventory.material_type__t AS imt ON pol.physical__material_type = imt.id JOIN inventory.location__t AS loc ON pol.physical__expected_receipt_date IS NOT NULL JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id JOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id WHERE camp.name = \'Smith College\' AND po.date_ordered::date >= (CURRENT_DATE - INTERVAL \'90 days\') GROUP BY imt.name ORDER BY total_purchased DESC;',NULL,NULL,1,1,'2026-02-19 20:39:13','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (133,'example',NULL,NULL,'How many items does each library have?','SELECT lib.name AS library_name, COUNT(ii.id) AS item_count FROM inventory.item__t AS ii JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id GROUP BY lib.name ORDER BY item_count DESC;',NULL,NULL,1,1,'2026-02-19 20:39:13','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (134,'example',NULL,NULL,'What vendors have we spent the most money with this fiscal year?','SELECT org.name AS vendor_name, SUM(inv.total) AS total_spent FROM invoice.invoices__t AS inv JOIN organizations.organizations__t AS org ON inv.vendor_id = org.id WHERE inv.status = \'Paid\' AND inv.invoice_date >= (SELECT start_date FROM finance.fiscal_year__t WHERE code = \'FY2026\') GROUP BY org.name ORDER BY total_spent DESC LIMIT 20;',NULL,NULL,1,1,'2026-02-19 20:39:13','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (135,'example',NULL,NULL,'Count checkouts by patron group for the Neilson Library in the last 30 days','SELECT ug.group AS patron_group, COUNT(al.id) AS checkout_count FROM circulation.audit_loan__t AS al JOIN inventory.item__t AS ii ON al.loan__item_id = ii.id JOIN users.users__t AS uu ON al.loan__user_id = uu.id JOIN users.groups__t AS ug ON uu.patron_group = ug.id JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id WHERE LOWER(lib.name) ILIKE \'%Neilson%\' AND al.loan__action IN (\'checkedout\', \'checkedOutThroughOverride\') AND al.loan__loan_date >= (CURRENT_DATE - INTERVAL \'30 days\') GROUP BY ug.group ORDER BY checkout_count DESC;',NULL,NULL,1,1,'2026-02-19 20:39:13','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (136,'example',NULL,NULL,'Show me the top 10 highest circulating books from Smith College between June 2024 and June 2025','SELECT lib.name AS library_name, ii.effective_call_number_components__call_number AS call_number, inst.title, MAX(al.loan__loan_date) AS last_circulation_date, COUNT(al.id) AS circulation_count FROM circulation.audit_loan__t AS al JOIN inventory.item__t AS ii ON al.loan__item_id = ii.id JOIN inventory.material_type__t AS imt ON ii.material_type_id = imt.id JOIN inventory.holdings_record__t AS hr ON ii.holdings_record_id = hr.id JOIN inventory.instance__t AS inst ON hr.instance_id = inst.id JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id JOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id WHERE al.loan__action IN (\'checkedout\', \'checkedOutThroughOverride\') AND al.loan__loan_date::date >= \'2024-06-30\' AND al.loan__loan_date::date <= \'2025-06-30\' AND LOWER(camp.name) = LOWER(\'Smith College\') AND LOWER(imt.name) = \'book\' AND LOWER(imt.name) NOT LIKE \'%equipment%\' GROUP BY lib.name, ii.effective_call_number_components__call_number, inst.title ORDER BY circulation_count DESC LIMIT 10;',NULL,NULL,1,1,'2026-02-19 20:39:13','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (139,'correction',NULL,NULL,'Show me the number of items that have circulated from Smith College to another Five College member. Only show me July 1st, 2024 to June 30th, 2025. I do not want to see items circulated to Smith College patrons only to other members within the Five Colleges.','WITH smith_sp AS (\n  SELECT unnest(array[\n    \'2c0764b7-63b3-4254-9950-0c730b7e438b\',\n    \'6b6b9f00-aac7-4e20-a819-fb24386e48bb\',\n    \'25d98f21-ef4d-4846-955e-17840062b1f0\',\n    \'602aba21-73ae-4e43-a92e-91f2dee34c8f\',\n    \'9e4b06c8-0cb0-4011-ab1d-a23af57d190c\'\n  ])::text AS id\n),\nkeep_materials AS (\n  SELECT unnest(array[\n    \'Book\',\'Journal\',\'Serial\',\'Newspaper\',\'Score\',\n    \'Thesis/Dissertation\',\'Government Publication\',\'Microform\',\n    \'DVD/Blu-ray\',\'Audio CD\',\'CD-ROM\',\'Videocassette\',\n    \'LP Phonorecord\',\'Audiocassette\',\'Film\'\n  ]) AS name\n),\nbase AS (\n  SELECT l.id, l.checkout_service_point_id AS co_sp,\n    l.checkin_service_point_id AS ci_sp,\n    loc.campus_id AS campus_at_co, mt.name AS mtype\n  FROM circulation.loan__t l\n  JOIN inventory.location__t loc ON loc.id = l.item_effective_location_id_at_check_out\n  JOIN inventory.item__t it ON it.id = l.item_id\n  JOIN inventory.material_type__t mt ON mt.id = it.material_type_id\n  WHERE l.loan_date::timestamptz >= \'2024-07-01\'\n    AND l.loan_date::timestamptz < \'2025-06-30\'\n    AND mt.name IN (SELECT name FROM keep_materials)\n    AND l.renewal_count IS NULL\n)\nSELECT\n  SUM(CASE\n    WHEN campus_at_co IN (\n      \'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\n      \'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\'\n    )\n    AND COALESCE(co_sp, \'\') NOT IN (SELECT id FROM smith_sp)\n    AND co_sp IS NOT NULL\n    THEN 1 ELSE 0\n  END) AS consortial_lending_out\nFROM base;','SELECT COUNT(DISTINCT cl.item_id) AS distinct_items_circulated FROM circulation.loan__t AS cl JOIN inventory.location__t AS loc_item ON cl.item_effective_location_id_at_check_out = loc_item.id JOIN inventory.loccampus__t AS camp_item ON loc_item.campus_id = camp_item.id JOIN users.users__t AS uu ON cl.user_id = uu.id JOIN inventory.loccampus__t AS camp_patron ON uu.custom_fields__institution = camp_patron.id WHERE cl.loan_date::date >= \'2024-07-01\' AND cl.loan_date::date <= \'2025-06-30\' AND LOWER(camp_item.name) = LOWER(\'Smith College\') AND LOWER(camp_patron.name) != LOWER(\'Smith College\') AND camp_patron.institution_id = (SELECT ic.institution_id FROM inventory.loccampus__t AS ic WHERE LOWER(ic.name) = LOWER(\'Smith College\')) LIMIT 100;','CRITICAL: User data is anonymized. NEVER join to users.users__t for campus/institution identification. Instead use checkout_service_point_id and checkin_service_point_id on circulation.loan__t as proxies. Smith-owned items checked out at non-Smith service points = consortial lending out. Also filter to physical material types and exclude renewals (renewal_count IS NULL). Smith campus IDs: 7d02e46d-3e60-4eaf-a986-5aa3550e8cb5 (Smith College), b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1 (Repository).',1,1,'2026-02-19 20:59:41','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (140,'vocabulary','anonymized data','User/patron records (users.users__t) are ANONYMIZED. NEVER use patron data (custom_fields, patron group joins, user campus fields) to determine which campus or institution a borrower belongs to. Instead, use checkout_service_point_id and checkin_service_point_id on circulation.loan__t as proxies for where transactions happened. Match service point IDs to known campus service points to identify cross-campus activity.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (141,'vocabulary','consortial circulation','To identify cross-campus lending/borrowing in the Five Colleges consortium, use this approach: (1) Item ownership = item_effective_location_id_at_check_out -> inventory.location__t.campus_id (Smith campus IDs: \'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\' for Smith College, \'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\' for Repository). (2) Transaction location = checkout_service_point_id / checkin_service_point_id matched against known campus service points. (3) Lending out = Smith-owned items checked out at NON-Smith service points. (4) Borrowing in = non-Smith-owned items checked out at Smith service points. NEVER use users.users__t joins â€” data is anonymized.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (142,'vocabulary','consortial lending','Same as \'consortial circulation\'. Lending out = Smith-owned items (campus_at_co in Smith/Repository campus IDs) where checkout_service_point_id is NOT a Smith service point. Use service points as proxy â€” NOT user/patron data (anonymized).',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (143,'vocabulary','consortial borrowing','Same as \'consortial circulation\'. Borrowing in = non-Smith-owned items (campus_at_co NOT in Smith/Repository campus IDs) where checkout_service_point_id IS a Smith service point. Use service points as proxy â€” NOT user/patron data (anonymized).',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (144,'vocabulary','Smith College service points','Smith College service point UUIDs for identifying transactions at Smith: \'2c0764b7-63b3-4254-9950-0c730b7e438b\' (SC Neilson Library), \'6b6b9f00-aac7-4e20-a819-fb24386e48bb\' (SC Self Check), \'25d98f21-ef4d-4846-955e-17840062b1f0\' (SC Hillyer Art Library), \'602aba21-73ae-4e43-a92e-91f2dee34c8f\' (SC Josten Library), \'9e4b06c8-0cb0-4011-ab1d-a23af57d190c\' (SC Annex). Use with checkout_service_point_id / checkin_service_point_id on circulation.loan__t.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (145,'vocabulary','Smith College campus IDs','Smith College campus UUIDs in inventory.loccampus__t for determining item ownership via item_effective_location_id_at_check_out -> location.campus_id: \'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\' (Smith College campus), \'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\' (Repository campus â€” also Smith-owned). Both should be included when identifying Smith-owned items.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (146,'vocabulary','renewal','circulation.audit_loan__t where loan__action = \'renewed\' â€” each renewal is a separate row in the audit table. Do NOT use loan__t.renewal_count to count renewals â€” in FOLIO initial checkouts have renewal_count = 0, not NULL, making it unreliable for filtering.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (147,'vocabulary','physical materials','When filtering for physical/tangible materials (excluding equipment and e-resources), use this list of material_type__t.name values: \'Book\', \'Journal\', \'Serial\', \'Newspaper\', \'Score\', \'Thesis/Dissertation\', \'Government Publication\', \'Microform\', \'DVD/Blu-ray\', \'Audio CD\', \'CD-ROM\', \'Videocassette\', \'LP Phonorecord\', \'Audiocassette\', \'Film\'. Build as a CTE with unnest(array[...]) for clean filtering.',NULL,NULL,NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (148,'example',NULL,NULL,'Show me Smith College physical circulation at Smith, consortial lending out, and consortial borrowing in for FY 2024-2025 (July 1 to June 30)','WITH smith_sp AS (\n  SELECT unnest(array[\n    \'2c0764b7-63b3-4254-9950-0c730b7e438b\',\n    \'6b6b9f00-aac7-4e20-a819-fb24386e48bb\',\n    \'25d98f21-ef4d-4846-955e-17840062b1f0\',\n    \'602aba21-73ae-4e43-a92e-91f2dee34c8f\',\n    \'9e4b06c8-0cb0-4011-ab1d-a23af57d190c\'\n  ])::text AS id\n),\nkeep_materials AS (\n  SELECT unnest(array[\n    \'Book\',\'Journal\',\'Serial\',\'Newspaper\',\'Score\',\n    \'Thesis/Dissertation\',\'Government Publication\',\'Microform\',\n    \'DVD/Blu-ray\',\'Audio CD\',\'CD-ROM\',\'Videocassette\',\n    \'LP Phonorecord\',\'Audiocassette\',\'Film\'\n  ]) AS name\n),\nbase AS (\n  SELECT l.id, l.loan_date::timestamptz AS loan_dt,\n    l.checkout_service_point_id AS co_sp,\n    l.checkin_service_point_id AS ci_sp,\n    loc.campus_id AS campus_at_co, mt.name AS mtype\n  FROM circulation.loan__t l\n  JOIN inventory.location__t loc ON loc.id = l.item_effective_location_id_at_check_out\n  JOIN inventory.item__t it ON it.id = l.item_id\n  JOIN inventory.material_type__t mt ON mt.id = it.material_type_id\n  WHERE l.loan_date::timestamptz >= \'2024-07-01\'\n    AND l.loan_date::timestamptz < \'2025-06-30\'\n    AND mt.name IN (SELECT name FROM keep_materials)\n    AND l.renewal_count IS NULL\n)\nSELECT\n  SUM(CASE\n    WHEN campus_at_co IN (\'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\')\n    AND co_sp IN (SELECT id FROM smith_sp)\n    AND (ci_sp IS NULL OR ci_sp IN (SELECT id FROM smith_sp))\n    THEN 1 ELSE 0\n  END) AS physical_circ_at_smith,\n  SUM(CASE\n    WHEN campus_at_co IN (\'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\')\n    AND COALESCE(co_sp, \'\') NOT IN (SELECT id FROM smith_sp)\n    AND co_sp IS NOT NULL\n    THEN 1 ELSE 0\n  END) AS consortial_lending_out,\n  SUM(CASE\n    WHEN campus_at_co NOT IN (\'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\')\n    AND co_sp IN (SELECT id FROM smith_sp)\n    THEN 1 ELSE 0\n  END) AS consortial_borrowing_in\nFROM base;',NULL,NULL,1,1,'2026-02-19 21:00:33','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (149,'vocabulary','campus abbreviation SC','SC = Smith College. Library and location names prefixed with SC belong to Smith College (e.g. SC Neilson Library, SC Hillyer Art Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:33:47','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (150,'vocabulary','campus abbreviation AC','AC = Amherst College. Library and location names prefixed with AC belong to Amherst College (e.g. AC Frost Library, AC Science Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:33:52','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (151,'vocabulary','campus abbreviation MH','MH = Mount Holyoke College. Library and location names prefixed with MH belong to Mount Holyoke College (e.g. MH Main Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (152,'vocabulary','campus abbreviation UM','UM = University Of Massachusetts. Library and location names prefixed with UM belong to UMass (e.g. UM W.E.B. Du Bois Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (153,'vocabulary','campus abbreviation HC','HC = Hampshire College. Library and location names prefixed with HC belong to Hampshire College (e.g. HC Harold Johnson Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (154,'vocabulary','campus abbreviation RP','RP = Five Colleges Collections. Library and location names prefixed with RP belong to the shared Five Colleges repository.',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (155,'vocabulary','campus abbreviation YB','YB = National Yiddish Book Center. Library and location names prefixed with YB belong to the Yiddish Book Center.',NULL,NULL,NULL,'Five Colleges naming convention',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (156,'vocabulary','location naming convention','In this Five Colleges FOLIO instance, ALL library names and location names are prefixed with a 2-letter campus abbreviation code (SC, AC, MH, UM, HC, RP, YB). When searching for a library or location by name, use ILIKE with a wildcard pattern to match regardless of prefix, e.g. WHERE name ILIKE \'%Neilson%\' instead of exact match.',NULL,NULL,NULL,'Five Colleges naming convention - general rule',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (157,'example','items at Neilson Library',NULL,'How many items are at Neilson Library?','SELECT COUNT(*) AS item_count FROM inventory.item__t ii JOIN inventory.location__t il ON ii.effective_location_id = il.id JOIN inventory.loclibrary__t ilb ON il.library_id = ilb.id WHERE ilb.name ILIKE \'%Neilson%\'',NULL,'Demonstrates using ILIKE wildcard for campus-prefixed library name (SC Neilson Library)',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (158,'example','Smith College libraries',NULL,'List all libraries at Smith College','SELECT ilb.name AS library_name, ilb.code AS library_code FROM inventory.loclibrary__t ilb JOIN inventory.loccampus__t ic ON ilb.campus_id = ic.id WHERE ic.name ILIKE \'%Smith%\' ORDER BY ilb.name',NULL,'Demonstrates joining library to campus to filter by campus name',1,1,'2026-02-20 15:34:56','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (159,'correction',NULL,NULL,'I want to see the entire library budget at Smith College. I want to look across multiple years from 2022 to current.','        SELECT \n            fyt.\"name\" AS fiscal_year, \n            SUM(bt.allocated) AS total_allocated\n        FROM \n            ldplite.finance.budget__t bt \n        INNER JOIN \n            ldplite.finance.fund__t ft ON bt.fund_id = ft.id\n        INNER JOIN \n            ldplite.finance.fiscal_year__t fyt ON bt.fiscal_year_id = fyt.id\n        WHERE \n            fyt.series = \'SCFY\'\n        GROUP BY \n            fyt.\"name\"\n        ORDER BY \n            fyt.\"name\"','SELECT\n  ffy.name AS fiscal_year,\n  SUM(fb.total_funding) AS total_budget_amount\nFROM finance.budget__t AS fb\nJOIN finance.fiscal_year__t AS ffy\n  ON fb.fiscal_year_id = ffy.id\nJOIN finance.budget__t__acq_unit_ids AS fbau\n  ON fb.id = fbau.id\nJOIN orders.acquisitions_unit__t AS oau\n  ON fbau.acq_unit_ids = oau.id\nWHERE\n  LOWER(oau.name) ILIKE \'%smith college%\' AND ffy.period_start::date >= \'2022-01-01\'\nGROUP BY\n  ffy.name\nORDER BY\n  ffy.name;','Questions about budget allocations should use fiscal_year__t and focus on the series which is the fiscal year allocation. Institutions use the abbreviation over their institution, SC for Smith College for example, to get their data.',1,1,'2026-02-20 15:55:29','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (160,'vocabulary','academic year','When a user says \'current year\', \'this year\', or \'academic year\', they mean the academic/fiscal year running July 1 through June 30. Never assume calendar year (Jan-Dec) unless the user explicitly says \'calendar year\'. To calculate the current academic year dynamically, ALWAYS use a CTE with the WITH keyword: WITH academic_year_dates AS ( SELECT CASE WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' ELSE date_trunc(\'year\', CURRENT_DATE) - INTERVAL \'6 months\' END AS start_date, CASE WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'1 year\' + INTERVAL \'6 months\' - INTERVAL \'1 day\' ELSE date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' - INTERVAL \'1 day\' END AS end_date ) â€” then reference it with: JOIN academic_year_dates ayd ON TRUE and filter with: WHERE date_column >= ayd.start_date AND date_column <= ayd.end_date. CRITICAL: The WITH keyword and CTE name \'academic_year_dates AS (\' must appear at the start of the query. If the query has other CTEs, chain them with commas after the academic_year_dates CTE.',NULL,NULL,NULL,'Five Colleges academic year - July 1 to June 30. Updated to emphasize WITH CTE wrapper.',1,1,'2026-02-20 15:59:50','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (161,'vocabulary','circulation data','Circulation data comes from TWO sources: (1) Current FOLIO circulation from circulation.loan__t (preferred, ~677K rows, faster) — columns use DIRECT names: item_id, loan_date, action, due_date, return_date, renewal_count, status__name. Filter checkouts with: action IN (\'checkedout\', \'checkedOutThroughOverride\'). Group by item_id. Do NOT use loan__ prefix on columns (that prefix is only for audit_loan__t). (2) Historic/former circulation from the ALEPH system (migrated in 2022), stored in inventory.item__t__notes where notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'. The note value is a plain text number that must be extracted with CAST(COALESCE(NULLIF(REGEXP_REPLACE(notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER). Join historic data to items via hrid (item__t__notes.hrid = item__t.hrid). When the user asks for TOTAL, LIFETIME, ALL-TIME, CUMULATIVE, or HIGHEST circulating items, include BOTH sources as separate columns plus a combined total: COALESCE(current, 0) + COALESCE(former, 0). When the user asks for circulation within a specific TIME PERIOD (e.g. \'this year\', \'last 30 days\'), use ONLY the current FOLIO circulation data — historic ALEPH data has no date granularity. IMPORTANT: Always prefer loan__t over audit_loan__t — loan__t is 3x smaller and has cleaner column names.',NULL,NULL,NULL,NULL,1,1,'2026-02-20 19:45:54','2026-02-27 17:53:35');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (162,'vocabulary','former circulation','\"Former circulation\", \"historic circulation\", or \"ALEPH circulation\", \"Cumulative circulation\", \"Total Circulation\" refers to cumulative checkout counts migrated from the ALEPH ILS into FOLIO item notes. Located in inventory.item__t__notes where notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'. The note contains a plain-text number. Extract it with: CAST(COALESCE(NULLIF(REGEXP_REPLACE(notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER). Join to item__t on hrid. Always LEFT JOIN since not all items have historic data.',NULL,NULL,NULL,NULL,1,1,'2026-02-20 19:47:09','2026-02-27 17:53:35');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (163,'example',NULL,NULL,'Show the highest circulating items at a specific library with total circulation','WITH target_items AS (\n    SELECT ii.id AS item_id, ii.hrid, ii.barcode,\n           ii.effective_call_number_components__call_number AS call_number,\n           inst.title AS instance_title,\n           mtt.name AS material_type,\n           loc.name AS location_name\n    FROM inventory.item__t ii\n    JOIN inventory.holdings_record__t hr ON ii.holdings_record_id = hr.id\n    JOIN inventory.instance__t inst ON hr.instance_id = inst.id\n    JOIN inventory.material_type__t imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t lib ON loc.library_id = lib.id\n    WHERE lib.name ILIKE \'%Neilson%\'\n      AND LOWER(imt.name) = \'book\'\n),\ncurrent_circ AS (\n    SELECT cl.item_id,\n           COUNT(*) AS current_circulation,\n           MAX(cl.loan_date) AS last_circulation_date\n    FROM circulation.loan__t cl\n    JOIN target_items ti ON cl.item_id = ti.item_id\n    WHERE cl.action IN (\'checkedout\', \'checkedOutThroughOverride\')\n    GROUP BY cl.item_id\n),\nformer_circ AS (\n    SELECT itn.hrid,\n           CAST(COALESCE(NULLIF(REGEXP_REPLACE(itn.notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER) AS former_circulation\n    FROM inventory.item__t__notes itn\n    JOIN target_items ti ON itn.hrid = ti.hrid\n    WHERE itn.notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'\n)\nSELECT\n    ti.instance_title,\n    ti.barcode AS item_barcode,\n    ti.call_number,\n    ti.material_type,\n    ti.location_name,\n    COALESCE(cc.current_circulation, 0) AS current_circulation,\n    COALESCE(fc.former_circulation, 0) AS former_circulation,\n    COALESCE(cc.current_circulation, 0) + COALESCE(fc.former_circulation, 0) AS total_circulation,\n    cc.last_circulation_date\nFROM target_items ti\nLEFT JOIN current_circ cc ON ti.item_id = cc.item_id\nLEFT JOIN former_circ fc ON ti.hrid = fc.hrid\nORDER BY total_circulation DESC\nLIMIT 100',NULL,'DEACTIVATED â€” superseded by ID 171. This example used circulation.loan__t instead of audit_loan__t.',0,1,'2026-02-20 19:47:38','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (164,'example','items created this year',NULL,'How many items were created this year?','WITH academic_year_dates AS (\n    SELECT\n        CASE\n            WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            ELSE date_trunc(\'year\', CURRENT_DATE) - INTERVAL \'6 months\'\n        END AS start_date,\n        CASE\n            WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'1 year\' + INTERVAL \'6 months\' - INTERVAL \'1 day\'\n            ELSE date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' - INTERVAL \'1 day\'\n        END AS end_date\n)\nSELECT COUNT(*) AS items_created\nFROM inventory.item__t i, academic_year_dates a\nWHERE i.metadata__created_date >= a.start_date\nAND i.metadata__created_date <= a.end_date',NULL,'Demonstrates the academic year CTE pattern. CRITICAL: query must start with WITH academic_year_dates AS ( ... ) â€” do not omit the WITH keyword.',1,1,'2026-02-24 15:49:12','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (165,'vocabulary','query performance optimization','CRITICAL PERFORMANCE RULES: (1) Always use circulation.loan__t (NOT audit_loan__t) for circulation queries â€” it is 3x smaller (677K vs 2.2M rows) and has cleaner column names (item_id, action, loan_date â€” no loan__ prefix). (2) When a query uses CTEs (WITH clauses) that aggregate large tables (e.g. circulation.loan__t, inventory.item__t__notes), ALWAYS define a target_items CTE FIRST that applies all WHERE filters (location, campus, material type, etc.), then JOIN the circulation/notes CTEs to target_items. BAD pattern (timeout): CTE aggregates ALL rows, outer query filters. GOOD pattern (fast): target_items CTE with filters first, then circulation CTE joins to target_items. (3) For circulation.loan__t columns: use item_id (NOT loan__item_id), action (NOT loan__action), loan_date (NOT loan__loan_date). The loan__ prefix columns are ONLY in audit_loan__t. (4) Filter checkouts with: action IN (\'checkedout\', \'checkedOutThroughOverride\').',NULL,NULL,NULL,'DEACTIVATED â€” superseded by ID 172. This hint incorrectly told Gemini to always prefer loan__t over audit_loan__t.',0,1,'2026-02-24 16:00:38','2026-03-06 09:49:37');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (166,'example','highest circulating books optimized',NULL,'Show the highest circulating books at Neilson Library with total circulation','WITH target_items AS (\n    SELECT ii.id AS item_id, ii.hrid, ii.barcode,\n           ii.effective_call_number_components__call_number AS call_number,\n           inst.title AS instance_title\n    FROM inventory.item__t ii\n    JOIN inventory.holdings_record__t hr ON ii.holdings_record_id = hr.id\n    JOIN inventory.instance__t inst ON hr.instance_id = inst.id\n    JOIN inventory.material_type__t imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t lib ON loc.library_id = lib.id\n    WHERE lib.name ILIKE \'%Neilson%\'\n      AND LOWER(imt.name) = \'book\'\n),\ncurrent_circ AS (\n    SELECT cl.item_id,\n           COUNT(*) AS current_circulation,\n           MAX(cl.loan_date) AS last_circulation_date\n    FROM circulation.loan__t cl\n    JOIN target_items ti ON cl.item_id = ti.item_id\n    WHERE cl.action IN (\'checkedout\', \'checkedOutThroughOverride\')\n    GROUP BY cl.item_id\n),\nformer_circ AS (\n    SELECT itn.hrid,\n           CAST(COALESCE(NULLIF(REGEXP_REPLACE(itn.notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER) AS former_circulation\n    FROM inventory.item__t__notes itn\n    JOIN target_items ti ON itn.hrid = ti.hrid\n    WHERE itn.notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'\n)\nSELECT\n    ti.instance_title,\n    ti.barcode AS item_barcode,\n    ti.call_number,\n    COALESCE(cc.current_circulation, 0) AS current_circulation,\n    COALESCE(fc.former_circulation, 0) AS former_circulation,\n    COALESCE(cc.current_circulation, 0) + COALESCE(fc.former_circulation, 0) AS total_circulation,\n    cc.last_circulation_date\nFROM target_items ti\nLEFT JOIN current_circ cc ON ti.item_id = cc.item_id\nLEFT JOIN former_circ fc ON ti.hrid = fc.hrid\nORDER BY total_circulation DESC\nLIMIT 20',NULL,'OPTIMIZED pattern using loan__t (NOT audit_loan__t). Defines target_items CTE first with all filters (location, material type), then current_circ and former_circ CTEs JOIN to target_items to only aggregate matching items. Uses circulation.loan__t with direct column names: item_id (NOT loan__item_id), action (NOT loan__action), loan_date (NOT loan__loan_date). Tested: completes in ~220 seconds for Neilson Library (271K books). ALWAYS use this 3-CTE pattern for circulation queries.',1,1,'2026-02-24 16:00:38','2026-02-27 17:53:35');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (167,'vocabulary','Current year','current data only â€” ignore inventory.item__t__notes with former circulation',NULL,NULL,NULL,NULL,1,1,'2026-02-26 13:48:42','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (168,'vocabulary','All time / historical / everything','include notes â€” combine circulation.loan__t + former circulation notes',NULL,NULL,NULL,NULL,1,1,'2026-02-26 13:49:15','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (169,'vocabulary','Ask for clarification','if the request is ambiguous (e.g., \"top circulating books\" without a time qualifier)',NULL,NULL,NULL,NULL,1,1,'2026-02-26 13:49:35','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (170,'vocabulary','circulation data','Circulation data comes from THREE sources: (1) circulation.audit_loan__t â€” the AUDIT LOG of all loan events (~2.2M rows). Use this for COUNTING checkouts. Each checkout/checkin/renewal is a separate row. Columns use the loan__ prefix: loan__item_id, loan__action, loan__loan_date, loan__due_date, loan__return_date. Filter checkouts with: loan__action IN (\'checkedout\', \'checkedOutThroughOverride\'). Group by loan__item_id. (2) circulation.loan__t â€” the CURRENT STATE of each loan (~677K rows). Each loan has ONE row showing its latest state. The action column shows the LAST action (e.g. \'checkedin\' for returned books). Use this ONLY for \"what is currently checked out\" queries (WHERE action = \'checkedout\'). Do NOT use loan__t for counting historical checkouts â€” a returned book has action=\'checkedin\', not \'checkedout\'. Columns have NO prefix: item_id, action, loan_date. (3) Historic/former circulation from the ALEPH system (migrated in 2022), stored in inventory.item__t__notes where notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'. The note value is a plain text number extracted with CAST(COALESCE(NULLIF(REGEXP_REPLACE(notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER). Join historic data to items via hrid. When the user asks for TOTAL, LIFETIME, ALL-TIME, or CUMULATIVE circulation, include audit_loan__t checkouts + former circulation notes. When the user asks for circulation within a specific TIME PERIOD (e.g. \'this year\', \'last 30 days\'), use ONLY audit_loan__t with date filters. NEVER use renewal_count IS NULL â€” it is unreliable. The action filter alone is sufficient.',NULL,NULL,NULL,NULL,1,1,'2026-02-26 15:51:06','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (171,'example',NULL,NULL,'Show the highest circulating items at a specific library with total circulation','WITH target_items AS (\n    SELECT ii.id AS item_id, ii.hrid, ii.barcode,\n           ii.effective_call_number_components__call_number AS call_number,\n           inst.title AS instance_title,\n           imt.name AS material_type,\n           loc.name AS location_name\n    FROM inventory.item__t ii\n    JOIN inventory.holdings_record__t hr ON ii.holdings_record_id = hr.id\n    JOIN inventory.instance__t inst ON hr.instance_id = inst.id\n    JOIN inventory.material_type__t imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t lib ON loc.library_id = lib.id\n    WHERE lib.name ILIKE \'%Neilson%\'\n      AND LOWER(imt.name) = \'book\'\n),\ncurrent_circ AS (\n    SELECT al.loan__item_id AS item_id,\n           COUNT(*) AS current_circulation,\n           MAX(al.loan__loan_date) AS last_circulation_date\n    FROM circulation.audit_loan__t al\n    JOIN target_items ti ON al.loan__item_id = ti.item_id\n    WHERE al.loan__action IN (\'checkedout\', \'checkedOutThroughOverride\')\n    GROUP BY al.loan__item_id\n),\nformer_circ AS (\n    SELECT itn.hrid,\n           CAST(COALESCE(NULLIF(REGEXP_REPLACE(itn.notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER) AS former_circulation\n    FROM inventory.item__t__notes itn\n    JOIN target_items ti ON itn.hrid = ti.hrid\n    WHERE itn.notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'\n)\nSELECT\n    ti.instance_title,\n    ti.barcode AS item_barcode,\n    ti.call_number,\n    ti.material_type,\n    ti.location_name,\n    COALESCE(cc.current_circulation, 0) AS current_circulation,\n    COALESCE(fc.former_circulation, 0) AS former_circulation,\n    COALESCE(cc.current_circulation, 0) + COALESCE(fc.former_circulation, 0) AS total_circulation,\n    cc.last_circulation_date\nFROM target_items ti\nLEFT JOIN current_circ cc ON ti.item_id = cc.item_id\nLEFT JOIN former_circ fc ON ti.hrid = fc.hrid\nORDER BY total_circulation DESC\nLIMIT 100',NULL,NULL,1,1,'2026-02-26 15:51:50','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (172,'vocabulary','query performance optimization','CRITICAL PERFORMANCE AND CORRECTNESS RULES: (1) Use circulation.audit_loan__t for counting checkouts â€” it has one row per loan EVENT. Filter with loan__action IN (\'checkedout\', \'checkedOutThroughOverride\'). Columns use the loan__ prefix: loan__item_id, loan__action, loan__loan_date. (2) Do NOT use circulation.loan__t for counting checkouts â€” it stores the CURRENT STATE of each loan. A returned book has action=\'checkedin\', so filtering action=\'checkedout\' misses all returned items. Only use loan__t for \"what is currently checked out right now\" queries. (3) When a query uses CTEs (WITH clauses) that aggregate large tables, ALWAYS define a target_items CTE FIRST that applies all WHERE filters (location, campus, material type, etc.), then JOIN the circulation/notes CTEs to target_items. BAD pattern (timeout): CTE aggregates ALL rows, outer query filters. GOOD pattern (fast): target_items CTE with filters first, then circulation CTE joins to target_items. (4) NEVER use renewal_count IS NULL to filter initial checkouts â€” in FOLIO, initial checkouts have renewal_count = 0, not NULL. The loan__action filter alone is sufficient to identify checkouts.',NULL,NULL,NULL,NULL,1,1,'2026-02-26 15:52:45','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (173,'example',NULL,NULL,'Show the highest circulating books at Neilson Library with total circulation','WITH target_items AS (\n    SELECT ii.id AS item_id, ii.hrid, ii.barcode,\n           ii.effective_call_number_components__call_number AS call_number,\n           inst.title AS instance_title\n    FROM inventory.item__t ii\n    JOIN inventory.holdings_record__t hr ON ii.holdings_record_id = hr.id\n    JOIN inventory.instance__t inst ON hr.instance_id = inst.id\n    JOIN inventory.material_type__t imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t lib ON loc.library_id = lib.id\n    WHERE lib.name ILIKE \'%Neilson%\'\n      AND LOWER(imt.name) = \'book\'\n),\ncurrent_circ AS (\n    SELECT al.loan__item_id AS item_id,\n           COUNT(*) AS current_circulation,\n           MAX(al.loan__loan_date) AS last_circulation_date\n    FROM circulation.audit_loan__t al\n    JOIN target_items ti ON al.loan__item_id = ti.item_id\n    WHERE al.loan__action IN (\'checkedout\', \'checkedOutThroughOverride\')\n    GROUP BY al.loan__item_id\n),\nformer_circ AS (\n    SELECT itn.hrid,\n           CAST(COALESCE(NULLIF(REGEXP_REPLACE(itn.notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER) AS former_circulation\n    FROM inventory.item__t__notes itn\n    JOIN target_items ti ON itn.hrid = ti.hrid\n    WHERE itn.notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'\n)\nSELECT\n    ti.instance_title,\n    ti.barcode AS item_barcode,\n    ti.call_number,\n    COALESCE(cc.current_circulation, 0) AS current_circulation,\n    COALESCE(fc.former_circulation, 0) AS former_circulation,\n    COALESCE(cc.current_circulation, 0) + COALESCE(fc.former_circulation, 0) AS total_circulation,\n    cc.last_circulation_date\nFROM target_items ti\nLEFT JOIN current_circ cc ON ti.item_id = cc.item_id\nLEFT JOIN former_circ fc ON ti.hrid = fc.hrid\nORDER BY total_circulation DESC\nLIMIT 20',NULL,NULL,1,1,'2026-02-26 15:53:10','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (174,'vocabulary','former circulation','\"Former circulation\", \"historic circulation\", or \"ALEPH circulation\", \"Cumulative circulation\", \"Total Circulation\" refers to cumulative checkout counts migrated from the ALEPH ILS into FOLIO item notes. Located in inventory.item__t__notes where notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'. The note contains a plain-text number. Extract it with: CAST(COALESCE(NULLIF(REGEXP_REPLACE(notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER). Join to item__t on hrid. Always LEFT JOIN since not all items have historic data.',NULL,NULL,NULL,NULL,1,1,'2026-02-26 15:53:34','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (175,'example',NULL,NULL,'How many items were created this year?','WITH academic_year_dates AS (\n    SELECT\n        CASE\n            WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            ELSE date_trunc(\'year\', CURRENT_DATE) - INTERVAL \'6 months\'\n        END AS start_date,\n        CASE\n            WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'1 year\' + INTERVAL \'6 months\' - INTERVAL \'1 day\'\n            ELSE date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' - INTERVAL \'1 day\'\n        END AS end_date\n)\nSELECT COUNT(*) AS items_created\nFROM inventory.item__t i, academic_year_dates a\nWHERE i.metadata__created_date >= a.start_date\nAND i.metadata__created_date <= a.end_date',NULL,NULL,1,1,'2026-02-26 15:53:59','2026-02-27 12:56:01');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (176,'vocabulary','call number ranges','When grouping or counting by call number range or classification, NEVER use LEFT(call_number, 1) as a range â€” this incorrectly groups all LC classes starting with H (H, HA, HB, HC, HF, HQ, etc.) into one bucket and completely mishandles Dewey numbers.\n\nUse this CASE expression to extract call number class correctly:\n\nCASE\n    -- LC Call Number: extract the leading letter(s) only (1-3 letters before the first digit)\n    WHEN effective_call_number_components__call_number ~ \'^[A-Z]{1,3}[0-9]\'\n    THEN REGEXP_REPLACE(effective_call_number_components__call_number, \'^([A-Z]{1,3})[0-9].*\', \'\\1\')\n    -- Dewey Call Number: extract the 3-digit hundred class (e.g. 823.914 â†’ 800)\n    WHEN effective_call_number_components__call_number ~ \'^[0-9]\'\n    THEN LPAD(\n            CAST(\n                FLOOR(CAST(REGEXP_REPLACE(effective_call_number_components__call_number, \'^([0-9]+).*\', \'\\1\') AS NUMERIC) / 100) * 100\n            AS TEXT),\n         3, \'0\')\n    ELSE \'Unknown\'\nEND AS call_number_class\n\nLC examples:\n  \'H 123\'    â†’ \'H\'\n  \'HA 456\'   â†’ \'HA\'\n  \'HF 1234\'  â†’ \'HF\'\n  \'QA 76\'    â†’ \'QA\'\n  \'PS 3561\'  â†’ \'PS\'\n\nDewey examples:\n  \'823.914\'  â†’ \'800\'\n  \'153.4\'    â†’ \'100\'\n  \'372.6\'    â†’ \'300\'\n\nWhen asked for \"call number range\" or \"call number prefix\" or \"classification\", apply this CASE expression. When asked for a broader grouping (LC subclass description like \"H = Social Sciences\"), also provide a label by JOINing or CASE-matching the extracted class against known LC class descriptions.\n\nWhen a user asks which call number RANGES have the highest circulation, use this expression in the GROUP BY and SELECT. Do NOT use LEFT(..., 1) or SUBSTRING(..., 1, 1).',NULL,NULL,NULL,NULL,1,1,'2026-03-02 11:20:20','2026-03-02 11:20:20');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (177,'vocabulary','library grouping','When a user lists multiple libraries (e.g. \"for Neilson, Josten, and Hillyer\") or says \"from each library\" or \"by library\", ALWAYS include the library name in SELECT and GROUP BY to show individual counts per library. This is the DEFAULT behavior â€” show one row per library.\n\nOnly combine libraries into a single total when the user explicitly says \"total\", \"combined\", \"altogether\", \"sum across\", or \"how many total\".\n\nExamples of INDIVIDUAL counts (GROUP BY lib.name):\n- \"circulation for Neilson, Josten and Hillyer\" â†’ one row per library\n- \"from each of the three libraries\" â†’ one row per library\n- \"for individual counts from Neilson and Hillyer\" â†’ one row per library\n- \"checkouts at Neilson and Josten\" â†’ one row per library\n- \"how many items at each library\" â†’ one row per library\n\nExamples of COMBINED total (no GROUP BY lib.name, or SUM across):\n- \"total circulation across Neilson, Josten and Hillyer\" â†’ single number\n- \"combined checkouts from all three libraries\" â†’ single number\n- \"how many altogether from Neilson and Josten\" â†’ single number\n\nWhen in doubt, default to individual counts per library.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 10:06:41','2026-03-06 10:06:41');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (178,'vocabulary','MARC record','MARC bibliographic data is stored in folio_source_record.records__t.parsed_record__content as a TEXT column (NOT JSONB). It contains a JSON string representation of the MARC record. To check if a MARC field exists (e.g. field 300), use: parsed_record__content ILIKE \'%\"300\"%\'. To check if a field does NOT exist: parsed_record__content NOT ILIKE \'%\"300\"%\'. To search for a specific subfield value: parsed_record__content ILIKE \'%\"650\"%somevalue%\'. NEVER use jsonb_exists(), jsonb_path_query(), ->> operator, or any JSONB functions on this column â€” it is TEXT. NEVER cast it to JSONB â€” the content is too large and the cast will timeout. Always use ILIKE/NOT ILIKE pattern matching for MARC field queries. Join to instances via: folio_source_record.records__t.external_ids_holder__instance_id = inventory.instance__t.id.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 10:15:44','2026-03-06 10:15:44');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (179,'correction',NULL,NULL,'100 Smith items that do not have a 300 field in their MARC record','SELECT\n    ii.hrid AS item_hrid,\n    ii.barcode,\n    inst.title AS instance_title,\n    SUBSTRING(fsr.parsed_record__content FROM 1 FOR 200) AS marc_snippet\nFROM inventory.item__t AS ii\nJOIN inventory.holdings_record__t AS hr ON ii.holdings_record_id = hr.id\nJOIN inventory.instance__t AS inst ON hr.instance_id = inst.id\nJOIN folio_source_record.records__t AS fsr ON inst.id = fsr.external_ids_holder__instance_id\nJOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id\nJOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id\nJOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id\nWHERE LOWER(camp.name) = LOWER(\'Smith College\')\n    AND fsr.parsed_record__content NOT ILIKE \'%\"300\"%\'\nLIMIT 100;','SELECT inst.hrid AS instance_hrid, inst.title AS instance_title, imt.name AS material_type_name, camp.name AS campus_name FROM inventory.instance__t AS inst JOIN inventory.holdings_record__t AS hr ON inst.id = hr.instance_id JOIN inventory.item__t AS ii ON hr.id = ii.holdings_record_id JOIN inventory.material_type__t AS imt ON ii.material_type_id = imt.id JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id JOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id LEFT JOIN folio_source_record.records__t AS fsr ON inst.id = fsr.external_ids_holder__instance_id WHERE LOWER(camp.name) = LOWER(\'Smith College\') AND LOWER(imt.name) = \'book\' AND NOT jsonb_exists(fsr.parsed_record__content, \'300\') LIMIT 100;','CRITICAL: folio_source_record.records__t.parsed_record__content is a TEXT column, NOT JSONB. Never use jsonb_exists(), jsonb_path_query(), or any JSONB operator (->, ->>, @>, ?) on this column. Always use ILIKE / NOT ILIKE for MARC field presence checks. Pattern: parsed_record__content NOT ILIKE \'%\"300\"%\' to find records missing MARC field 300.',1,1,'2026-03-06 10:15:44','2026-03-06 10:15:44');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (180,'table_description','folio_source_record.records__t','Source bibliographic records (MARC, etc.) in their original format. CRITICAL: The parsed_record__content column is stored as TEXT (not JSONB) containing a JSON string of the full MARC record. Use ILIKE/NOT ILIKE for searching â€” NEVER use JSONB functions (jsonb_exists, ->>, @>, etc.). Join to instances via external_ids_holder__instance_id = inventory.instance__t.id.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 10:15:44','2026-03-06 10:15:44');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (181,'vocabulary','marctab_performance','When querying folio_source_record.marctab (a VIEW over ~1000 underlying tables), performance depends on TWO factors:\n\n1. INSTANCE SCOPING: Always materialize a small set of target instance_hrids FIRST using a CTE with AS MATERIALIZED. Never let the planner inline the CTE â€” large NOT EXISTS or LEFT JOIN against the full marctab view will time out.\n\n2. ITEM-LEVEL FILTERING: When the instance set depends on item-level conditions (material type, status, etc.), use nested EXISTS driving from instances â†’ holdings â†’ items. If idx_item_holdings_material exists on item__t(holdings_record_id, material_type_id), each probe is an index seek instead of a 10M-row seq scan.\n\nCanonical pattern for \"instances with item filter X missing MARC field Y\":\n\nWITH target_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = :campusCode\n          AND EXISTS (\n              SELECT 1 FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND ii.material_type_id = (\n                    SELECT id FROM inventory.material_type__t WHERE LOWER(name) = :materialType LIMIT 1\n                )\n          )\n    )\n)\nSELECT t.hrid, t.title\nFROM target_instances t\nWHERE NOT EXISTS (\n    SELECT 1 FROM folio_source_record.marctab m\n    WHERE m.instance_hrid = t.hrid AND m.field = :fieldCode\n)\n\nThis pattern: (a) materializes the small campus+item scoped set, (b) leverages the composite index for item probes, (c) does index lookups against marctab instead of scanning the full view.',NULL,NULL,NULL,'DEACTIVATED â€” folio_source_record.marctab VIEW scans ~1000 tables (668K cost). Use marctab.mtNNN per-field tables instead.',0,1,'2026-03-06 12:28:29','2026-03-12 16:40:33');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (182,'example',NULL,NULL,'Find all Smith College records missing a 300 field (physical description)','WITH sc_instances AS (\n    SELECT DISTINCT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1 FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id AND camp.code = \'SC\'\n    )\n)\nSELECT si.title, si.hrid\nFROM sc_instances si\nWHERE NOT EXISTS (\n    SELECT 1 FROM folio_source_record.marctab m\n    WHERE m.instance_hrid = si.hrid AND m.field = \'300\'\n)',NULL,'DEACTIVATED â€” folio_source_record.marctab VIEW scans ~1000 tables (668K cost). Use marctab.mtNNN per-field tables instead.',0,1,'2026-03-06 12:28:44','2026-03-12 16:40:33');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (183,'example',NULL,NULL,'Show all Smith College titles with their full MARC 245 (title) and 300 (physical description) data','WITH sc_instances AS (\n    SELECT DISTINCT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1 FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id AND camp.code = \'SC\'\n    )\n)\nSELECT\n    si.hrid,\n    si.title,\n    m245.sf AS title_subfield,\n    m245.content AS title_content,\n    m300.sf AS description_subfield,\n    m300.content AS description_content\nFROM sc_instances si\nLEFT JOIN folio_source_record.marctab m245\n    ON m245.instance_hrid = si.hrid AND m245.field = \'245\'\nLEFT JOIN folio_source_record.marctab m300\n    ON m300.instance_hrid = si.hrid AND m300.field = \'300\'\nORDER BY si.hrid, m245.ord, m245.sf, m300.ord, m300.sf',NULL,'DEACTIVATED â€” folio_source_record.marctab VIEW scans ~1000 tables (668K cost). Use marctab.mtNNN per-field tables instead.',0,1,'2026-03-06 12:28:51','2026-03-12 16:40:33');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (184,'example',NULL,NULL,'List Smith College titles with full 245 title string and all subject headings (650)','WITH sc_instances AS (\n    SELECT DISTINCT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1 FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id AND camp.code = \'SC\'\n    )\n)\nSELECT\n    si.hrid,\n    si.title,\n    STRING_AGG(DISTINCT m245.content, \' \' ORDER BY m245.content) AS full_title_245,\n    STRING_AGG(DISTINCT m650.content, \' ; \' ORDER BY m650.content) AS subjects_650\nFROM sc_instances si\nLEFT JOIN folio_source_record.marctab m245\n    ON m245.instance_hrid = si.hrid AND m245.field = \'245\'\nLEFT JOIN folio_source_record.marctab m650\n    ON m650.instance_hrid = si.hrid AND m650.field = \'650\'\nGROUP BY si.id, si.hrid, si.title\nORDER BY si.hrid',NULL,'DEACTIVATED â€” folio_source_record.marctab VIEW scans ~1000 tables (668K cost). Use marctab.mtNNN per-field tables instead.',0,1,'2026-03-06 12:28:59','2026-03-12 16:40:33');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (185,'example',NULL,NULL,'Show all raw MARC fields for a specific instance by hrid','SELECT\n    m.instance_hrid,\n    m.field,\n    m.ind1,\n    m.ind2,\n    m.ord,\n    m.sf,\n    m.content\nFROM folio_source_record.marctab m\nWHERE m.instance_hrid = :instanceHrid\nORDER BY m.field, m.ord, m.sf',NULL,'DEACTIVATED â€” folio_source_record.marctab VIEW scans ~1000 tables (668K cost). Use marctab.mtNNN per-field tables instead.',0,1,'2026-03-06 12:29:08','2026-03-12 16:40:33');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (186,'vocabulary','marctab_join_safety','CRITICAL: marctab.mtNNN tables have instance_id as UUID type but inventory.instance__t.id may be TEXT type. Joining on these columns causes ERROR: operator does not exist: uuid = text. ALWAYS join on instance_hrid instead: marctab.mtNNN.instance_hrid = inventory.instance__t.hrid (both text, safe to compare). This applies to ALL marctab tables (mt000â€“mt999).',NULL,NULL,NULL,NULL,1,1,'2026-03-06 12:29:16','2026-03-12 16:40:58');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (187,'vocabulary','marctab per-field table structure','The marctab schema contains one table per MARC field: marctab.mt000 through marctab.mt999. Each table contains ONLY rows for that MARC tag.\n\nColumns per table: srs_id (UUID), instance_hrid (text, links to inventory.instance__t.hrid), instance_id (UUID), field (tag, e.g. \'300\'), ind1, ind2, ord (occurrence number for repeated fields), sf (subfield code, e.g. \'a\', \'b\'), content (subfield value text).\n\nSubfields are ROWS (not columns). Each row is one subfield occurrence.\nTo get 245$a title: SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = inst.hrid AND m.sf = \'a\' LIMIT 1\nFor multiple subfields, use scalar subqueries per subfield (see hint \'marctab performance rule\').\n\nNEVER use folio_source_record.marctab (the VIEW) — always use marctab.mtNNN directly for guaranteed performance.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 12:29:24','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (188,'vocabulary','marctab common field tables','Common marctab per-field tables (all share columns: srs_id, instance_hrid, instance_id, field, ind1, ind2, ord, sf, content):\n  marctab.mt001 — control number\n  marctab.mt008 — fixed-length data elements\n  marctab.mt020 — ISBN (sf=\'a\')\n  marctab.mt022 — ISSN (sf=\'a\')\n  marctab.mt035 — system control number / OCLC (sf=\'a\')\n  marctab.mt050 — LC call number (sf=\'a\' + sf=\'b\')\n  marctab.mt082 — Dewey (sf=\'a\')\n  marctab.mt100 — main author (sf=\'a\')\n  marctab.mt245 — title (sf=\'a\' title, sf=\'b\' subtitle, sf=\'c\' responsibility)\n  marctab.mt246 — variant title (sf=\'a\')\n  marctab.mt260 — publication old format (sf=\'a\' place, sf=\'b\' publisher, sf=\'c\' date)\n  marctab.mt264 — publication (sf=\'a\' place, sf=\'b\' publisher, sf=\'c\' date)\n  marctab.mt300 — physical description (sf=\'a\' extent, sf=\'b\' other details, sf=\'c\' dimensions)\n  marctab.mt490 — series statement\n  marctab.mt500 — general note (sf=\'a\')\n  marctab.mt504 — bibliography note\n  marctab.mt520 — summary (sf=\'a\')\n  marctab.mt600 — subject person (sf=\'a\')\n  marctab.mt650 — subject topical (sf=\'a\' topic, sf=\'x\' general subdivision, sf=\'z\' geographic)\n  marctab.mt655 — genre/form (sf=\'a\')\n  marctab.mt700 — added author (sf=\'a\')\n  marctab.mt856 — electronic access (sf=\'u\' URL)\n\nQuery pattern: (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = inst.hrid AND m.sf = \'a\' LIMIT 1)\nAlways query the SPECIFIC marctab.mtNNN table, never the VIEW.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 12:29:31','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (189,'vocabulary','item__t index awareness','CRITICAL: inventory.item__t benefits from a composite index on (holdings_record_id, material_type_id). Create it with:\n\nCREATE INDEX CONCURRENTLY idx_item_holdings_material\nON inventory.item__t (holdings_record_id, material_type_id);\n\nWhen querying items by holdings or material type, ALWAYS structure queries to take advantage of this index:\n- Drive from holdings â†’ items using holdings_record_id (index leading column)\n- Filter by material_type_id in the same lookup (index second column)\n- Use nested EXISTS (not JOIN + DISTINCT) so PostgreSQL can do index-only semi-join probes\n- NEVER scan item__t first and then join back to holdings â€” that forces a 10M+ row seq scan\n\nCAVEAT: LDP/MetaDB rebuilds tables nightly. If the index is dropped during refresh, re-create it via a post-refresh script or cron job.\n\nThe ONLY default indexes on item__t are:\n- item__t_id_idx (id)\n- item__t___id_idx (__id)\n\nWithout idx_item_holdings_material, any EXISTS or JOIN through holdings_record_id does a full sequential scan.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 18:00:00','2026-03-12 16:31:47');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (190,'vocabulary','nested EXISTS pattern for instance-level queries with item-level filters','CRITICAL PERFORMANCE RULE: When building instance-level result sets with item-level filters (material type, item status, etc.), ALWAYS use nested EXISTS with MATERIALIZED CTEs. Never use JOIN + DISTINCT.\n\nPATTERN:\nWITH result AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        WHERE hr.instance_id = inst.id\n          AND [any holdings-level filters]\n          AND EXISTS (\n              SELECT 1\n              FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND [any item-level filters like material_type_id]\n          )\n    )\n)\n\nThis pattern:\n1. Uses the index on holdings_record__t(instance_id) to find holdings for each instance\n2. Uses the composite index idx_item_holdings_material on item__t(holdings_record_id, material_type_id) to check items\n3. EXISTS is a semi-join â€” stops at first match per instance\n4. MATERIALIZED prevents the planner from inlining the CTE and making bad join order decisions\n\nFor material type filtering, resolve the material_type_id with a scalar subquery:\n  ii.material_type_id = (SELECT id FROM inventory.material_type__t WHERE LOWER(name) = \'book\' LIMIT 1)\n\nThis avoids joining the material_type__t table into the main query, which can confuse the planner.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 18:00:00','2026-03-06 18:00:00');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (191,'vocabulary','MARC source record access','When a user requests MARC record data, use the appropriate approach:\n\n1. FIELD-LEVEL queries (check existence, extract subfield, filter by value): Use marctab.mtNNN per-field tables.\n   To extract subfield a from mt245: (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = inst.hrid AND m.sf = \'a\' LIMIT 1)\n\n2. FULL MARC record output (raw source, complete MARC, export): Use folio_source_record.records__t.parsed_record__content.\n   JOIN folio_source_record.records__t sr ON sr.external_id = inst.id AND sr.state = \'ACTUAL\'\n\nPrefer marctab.mtNNN over the folio_source_record.marctab VIEW for reliable performance.\n\nUse records__t.parsed_record__content when the user wants: the full/complete MARC record, raw source record, MARC data for export.\nUse marctab.mtNNN when the user wants: to check if a field exists, filter by a subfield value, extract specific subfields.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 18:00:00','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (192,'vocabulary','CTE MATERIALIZED keyword','ALWAYS use AS MATERIALIZED for CTEs that scope instances by campus, location, or any multi-table filter chain. Without MATERIALIZED, PostgreSQL 12+ may inline the CTE and make catastrophic join order decisions on large tables.\n\nExample:\nWITH sc_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (...)\n)\n\nThis forces PostgreSQL to:\n1. Execute the CTE first and store results in memory/temp\n2. Use accurate row counts for subsequent query planning\n3. Prevent the optimizer from flattening CTEs into joins that trigger full seq scans on 10M+ row tables',NULL,NULL,NULL,NULL,1,1,'2026-03-06 18:00:00','2026-03-06 18:00:00');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (193,'example',NULL,NULL,'Smith College instances with material type Book that are missing MARC field 300','WITH sc_book_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = \'SC\'\n          AND EXISTS (\n              SELECT 1\n              FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND ii.material_type_id = (\n                    SELECT id FROM inventory.material_type__t\n                    WHERE LOWER(name) = \'book\' LIMIT 1\n                )\n          )\n    )\n)\nSELECT sbi.hrid, sbi.title\nFROM sc_book_instances sbi\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM marctab.mt300 m\n    WHERE m.instance_hrid = sbi.hrid\n)\nLIMIT 100',NULL,'Uses marctab.mt300 per-field table instead of the VIEW. No field filter needed â€” the table IS the filter. MATERIALIZED CTE + nested EXISTS for item scoping.',1,1,'2026-03-06 18:00:00','2026-03-12 16:41:29');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (194,'example',NULL,NULL,'Show me the full MARC source record for Smith College books','WITH sc_book_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = \'SC\'\n          AND EXISTS (\n              SELECT 1\n              FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND ii.material_type_id = (\n                    SELECT id FROM inventory.material_type__t\n                    WHERE LOWER(name) = \'book\' LIMIT 1\n                )\n          )\n    )\n)\nSELECT sbi.hrid, sbi.title, sr.parsed_record__content\nFROM sc_book_instances sbi\nJOIN folio_source_record.records__t sr ON sr.external_id = sbi.id AND sr.state = \'ACTUAL\'\nLIMIT 100',NULL,'When user requests MARC record data or source records, ALWAYS include parsed_record__content from records__t. Join via external_id = instance.id with state = ACTUAL.',1,1,'2026-03-06 18:00:00','2026-03-06 18:00:00');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (195,'example',NULL,NULL,'Smith College instances missing a MARC 300 field with their source record','WITH sc_no_300 AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = \'SC\'\n    )\n    AND NOT EXISTS (\n        SELECT 1\n        FROM marctab.mt300 m\n        WHERE m.instance_hrid = inst.hrid\n    )\n)\nSELECT sn.hrid, sn.title, sr.parsed_record__content\nFROM sc_no_300 sn\nJOIN folio_source_record.records__t sr ON sr.external_id = sn.id AND sr.state = \'ACTUAL\'\nLIMIT 100',NULL,'Uses marctab.mt300 for field absence check (no field filter needed). records__t for full MARC output.',1,1,'2026-03-06 18:00:00','2026-03-12 16:41:35');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (196,'correction',NULL,NULL,'Smith instances that do not have a 300 field in their MARC record and a FOLIO material type of Book','WITH sc_book_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = \'SC\'\n          AND EXISTS (\n              SELECT 1\n              FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND ii.material_type_id = (\n                    SELECT id FROM inventory.material_type__t\n                    WHERE LOWER(name) = \'book\' LIMIT 1\n                )\n          )\n    )\n)\nSELECT sbi.hrid, sbi.title\nFROM sc_book_instances sbi\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM marctab.mt300 m\n    WHERE m.instance_hrid = sbi.hrid\n)\nLIMIT 100','WITH sc_book_instances AS (\n    SELECT DISTINCT\n        inst.id AS instance_id,\n        inst.hrid AS instance_hrid,\n        inst.title\n    FROM inventory.instance__t AS inst\n    JOIN inventory.holdings_record__t AS hr ON inst.id = hr.instance_id\n    JOIN inventory.item__t AS ii ON hr.id = ii.holdings_record_id\n    JOIN inventory.material_type__t AS imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id\n    JOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id\n    WHERE LOWER(camp.name) = LOWER(\'Smith College\')\n      AND LOWER(imt.name) = \'book\'\n)\nSELECT sbi.instance_hrid, sbi.title\nFROM sc_book_instances AS sbi\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM folio_source_record.marctab AS m\n    WHERE m.instance_hrid = sbi.instance_hrid\n      AND m.field = \'300\'\n)\nLIMIT 100','Uses marctab.mt300 per-field table â€” NOT the folio_source_record.marctab VIEW (668K cost). No AND m.field = \'300\' needed â€” the table IS the filter. Nested EXISTS + MATERIALIZED for item scoping.',1,1,'2026-03-06 18:00:00','2026-03-12 16:41:42');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (197,'vocabulary','MARC data','When a user asks about MARC fields or MARC records, use marctab.mtNNN per-field tables (e.g. marctab.mt245 for title, marctab.mt300 for physical description). Each table has columns: srs_id, instance_hrid, instance_id, field, ind1, ind2, ord, sf (subfield code), content (subfield value).\n\nTo extract a specific subfield, use SCALAR SUBQUERIES — NOT LEFT JOIN + GROUP BY:\n  GOOD (index probe per instance, EXPLAIN cost ~16K across 257K instances):\n    (SELECT m.content FROM marctab.mt300 m WHERE m.instance_hrid = si.hrid AND m.sf = \'a\' LIMIT 1) AS extent_300a\n  BAD (full table scan + merge join on millions of rows, cost ~2.1M):\n    LEFT JOIN marctab.mt245 m245 ON m245.instance_hrid = sbi.hrid ... GROUP BY ... MAX(CASE WHEN m245.sf = \'a\' ...)\n\nPrefer marctab.mtNNN over the folio_source_record.marctab VIEW for reliable performance.\n\nWhen a user says \"show me the MARC record\" or \"expand the MARC data\", either:\n  (a) Use scalar subqueries from the specific marctab.mtNNN tables for the fields they care about, OR\n  (b) Use folio_source_record.records__t.parsed_record__content for the complete raw MARC JSON.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 16:39:06','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (198,'vocabulary','MARC field','A specific MARC tag number (e.g. 245, 300, 650). Use the corresponding marctab.mtNNN table:\n  marctab.mt245 for field 245, marctab.mt300 for field 300, marctab.mt650 for field 650, etc.\n\nSubfields are ROWS — each row has sf (subfield code) and content (subfield value). There are NO sf_a, sf_b, sf_c columns.\n  Example: (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = inst.hrid AND m.sf = \'a\' LIMIT 1)\n\nord column distinguishes repeated fields (e.g. first 650 has ord=1, second has ord=2).\n\nTo check if a MARC field EXISTS:\n  WHERE EXISTS (SELECT 1 FROM marctab.mt300 m WHERE m.instance_hrid = inst.hrid)\n\nTo check if a MARC field DOES NOT EXIST:\n  WHERE NOT EXISTS (SELECT 1 FROM marctab.mt300 m WHERE m.instance_hrid = inst.hrid)\n\nPrefer marctab.mtNNN over folio_source_record.marctab WHERE field = \'NNN\' for reliable performance and Index Only Scan eligibility.',NULL,NULL,NULL,NULL,1,1,'2026-03-06 16:39:28','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (199,'vocabulary','marctab','MARC data is accessed via the marctab schema, which has one table per MARC field: marctab.mt000 through marctab.mt999.\n\nEach table has columns: srs_id, instance_hrid, instance_id, field, ind1, ind2, ord, sf (subfield code like \'a\', \'b\'), content (subfield value). There are NO sf_a, sf_b, etc. columns.\n\nSubfields are ROWS (not columns): filter by m.sf = \'a\' and read m.content.\n\nJoin to inventory via: marctab.mtNNN.instance_hrid = inventory.instance__t.hrid\n\nNOTE: There is a VIEW called folio_source_record.marctab that unions all ~1000 tables. PostgreSQL can sometimes prune this to a single underlying table, but mtNNN is preferred for guaranteed performance and Index Only Scan eligibility.\n\nExamples:\n  - Check field 300 exists: EXISTS (SELECT 1 FROM marctab.mt300 m WHERE m.instance_hrid = inst.hrid)\n  - Get ISBN: (SELECT m.content FROM marctab.mt020 m WHERE m.instance_hrid = inst.hrid AND m.sf = \'a\' LIMIT 1)\n  - Get title: (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = inst.hrid AND m.sf = \'a\' LIMIT 1)',NULL,NULL,NULL,NULL,1,1,'2026-03-06 16:39:56','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (200,'vocabulary','MARC query with item filter performance','When a MARC query also filters by item-level attributes (material type, item status, location), the TWO biggest performance factors are:\n\n1. idx_item_holdings_material index on inventory.item__t(holdings_record_id, material_type_id) â€” turns each nested EXISTS probe from a 10M-row seq scan into an index seek. Without this index, the item__t EXISTS check alone can take minutes.\n\n2. AS MATERIALIZED on the instance-scoping CTE â€” prevents PostgreSQL from inlining the CTE and making bad join-order decisions against the marctab view.\n\nBoth are required for sub-second performance on queries like \"Smith College books missing MARC field 300\". If the query times out, check that the composite index exists:\n  SELECT indexname FROM pg_indexes WHERE tablename = \'item__t\' AND indexdef LIKE \'%holdings_record_id%material_type_id%\';\n\nIf missing, create it:\n  CREATE INDEX CONCURRENTLY idx_item_holdings_material ON inventory.item__t (holdings_record_id, material_type_id);',NULL,NULL,NULL,'Links the composite index and MATERIALIZED CTE to MARC query performance. Both are needed.',1,1,'2026-03-12 16:31:47','2026-03-12 16:31:47');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (201,'vocabulary','marctab performance rule','CRITICAL PERFORMANCE RULE for MARC queries (EXPLAIN-verified 2026-03-13):\n\n1. ALWAYS use marctab.mtNNN per-field tables (e.g. marctab.mt300, marctab.mt245).\n   Columns: srs_id, instance_hrid, instance_id, field, ind1, ind2, ord, sf, content.\n   Indexed on instance_hrid. NOT EXISTS check: Index Only Scan at cost ~0.74/probe.\n\n2. For subfield extraction, use SCALAR SUBQUERIES — NOT LEFT JOIN + GROUP BY:\n   GOOD (cost ~16K overhead for 257K instance set):\n     (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = si.hrid AND m.sf = \'a\' LIMIT 1) AS title_a\n     (SELECT m.content FROM marctab.mt300 m WHERE m.instance_hrid = si.hrid AND m.sf = \'a\' LIMIT 1) AS extent_a\n   BAD (cost ~2.1M — full table scans + merge joins on 25M+ rows):\n     LEFT JOIN marctab.mt245 m245 ON m245.instance_hrid = sbi.hrid ... GROUP BY ... MAX(CASE WHEN m245.sf = \'a\' ...)\n\n3. For repeated fields (e.g. all 650 subjects), use a scalar subquery with STRING_AGG:\n     (SELECT STRING_AGG(m.content, \' ; \' ORDER BY m.ord) FROM marctab.mt650 m WHERE m.instance_hrid = si.hrid AND m.sf = \'a\')\n\n4. For complete raw MARC output, use folio_source_record.records__t.parsed_record__content.\n\n5. Combine with MATERIALIZED CTEs and nested EXISTS for instance scoping (see hints 190, 192).\n\n6. The folio_source_record.marctab VIEW can sometimes optimize via branch pruning but mtNNN is preferred for guaranteed performance.',NULL,NULL,NULL,'Replaces deactivated hint 181. The VIEW approach never worked â€” 668K cost even with CTE scoping.',1,1,'2026-03-12 16:43:30','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (202,'example',NULL,NULL,'Show Smith College book titles with their MARC 245 title and 300 physical description','WITH sc_book_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = \'SC\'\n          AND EXISTS (\n              SELECT 1\n              FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND ii.material_type_id = (\n                    SELECT id FROM inventory.material_type__t\n                    WHERE LOWER(name) = \'book\' LIMIT 1\n                )\n          )\n    )\n)\nSELECT\n    sbi.hrid,\n    sbi.title,\n    (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = sbi.hrid AND m.sf = \'a\' LIMIT 1) AS title_245a,\n    (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = sbi.hrid AND m.sf = \'b\' LIMIT 1) AS title_245b,\n    (SELECT m.content FROM marctab.mt245 m WHERE m.instance_hrid = sbi.hrid AND m.sf = \'c\' LIMIT 1) AS title_245c,\n    (SELECT m.content FROM marctab.mt300 m WHERE m.instance_hrid = sbi.hrid AND m.sf = \'a\' LIMIT 1) AS extent_300a,\n    (SELECT m.content FROM marctab.mt300 m WHERE m.instance_hrid = sbi.hrid AND m.sf = \'b\' LIMIT 1) AS other_details_300b,\n    (SELECT m.content FROM marctab.mt300 m WHERE m.instance_hrid = sbi.hrid AND m.sf = \'c\' LIMIT 1) AS dimensions_300c\nFROM sc_book_instances sbi\nORDER BY sbi.hrid\nLIMIT 100',NULL,'Uses scalar subqueries for subfield extraction (EXPLAIN cost ~16K) — NOT LEFT JOIN + GROUP BY (cost ~2.1M). Subfields are rows: filter by sf, read content. Replaces deactivated hint 183.',1,1,'2026-03-12 16:43:30','2026-03-13 14:28:15');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (203,'example',NULL,NULL,'List Smith College book titles with their subject headings','WITH sc_book_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id\n          AND camp.code = \'SC\'\n          AND EXISTS (\n              SELECT 1\n              FROM inventory.item__t ii\n              WHERE ii.holdings_record_id = hr.id\n                AND ii.material_type_id = (\n                    SELECT id FROM inventory.material_type__t\n                    WHERE LOWER(name) = \'book\' LIMIT 1\n                )\n          )\n    )\n)\nSELECT\n    sbi.hrid,\n    sbi.title,\n    (SELECT STRING_AGG(m.content, \' ; \' ORDER BY m.ord)\n     FROM marctab.mt650 m\n     WHERE m.instance_hrid = sbi.hrid AND m.sf = \'a\')\n    AS subjects\nFROM sc_book_instances sbi\nORDER BY sbi.hrid\nLIMIT 100',NULL,'Uses scalar subquery with STRING_AGG for repeated 650 fields. Filters sf=\'a\' for topic subfield only. Replaces deactivated hint 184.',1,1,'2026-03-12 16:43:30','2026-03-13 14:22:41');
INSERT INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `user_id`, `created_at`, `updated_at`) VALUES (204,'correction',NULL,NULL,'Smith instances missing MARC field 300','WITH sc_instances AS MATERIALIZED (\n    SELECT inst.id, inst.hrid, inst.title\n    FROM inventory.instance__t inst\n    WHERE EXISTS (\n        SELECT 1\n        FROM inventory.holdings_record__t hr\n        JOIN inventory.location__t loc ON loc.id = hr.permanent_location_id\n        JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id\n        JOIN inventory.loccampus__t camp ON camp.id = lib.campus_id\n        WHERE hr.instance_id = inst.id AND camp.code = \'SC\'\n    )\n)\nSELECT si.hrid, si.title\nFROM sc_instances si\nWHERE NOT EXISTS (\n    SELECT 1 FROM marctab.mt300 m\n    WHERE m.instance_hrid = si.hrid\n)\nLIMIT 100','SELECT si.hrid, si.title\nFROM sc_instances si\nWHERE NOT EXISTS (\n    SELECT 1 FROM folio_source_record.marctab m\n    WHERE m.instance_hrid = si.hrid AND m.field = \'300\'\n)\nLIMIT 100','CRITICAL: folio_source_record.marctab is a VIEW that unions ~1000 marctab.mtNNN tables. Even with AND m.field = \'300\' and a MATERIALIZED CTE, PostgreSQL scans ALL 1000 tables (668K cost). Use marctab.mt300 directly â€” single table, indexed on instance_hrid, no field filter needed.',1,1,'2026-03-12 16:43:30','2026-03-12 16:43:30');
